import{_ as s,a8 as r,o as u,c as i,au as p,a as g,a3 as e,K as o,L as a}from"./chunks/framework.Bftk7dsM.js";import"./chunks/theme.C-z6hHSd.js";const f=JSON.parse('{"title":"三大编码 Agent 都没有记忆库，只有一堆 Markdown 文件","description":"","frontmatter":{"title":"三大编码 Agent 都没有记忆库，只有一堆 Markdown 文件","abstract":"Codex、Claude Code、Cursor 三家的跨会话记忆，没有一家用向量库。它们的共同点是：常驻内容极小、细节延迟读取、写入端拼命做减法。真正难的不是存，是决定不存什么。","created":"2026-11-09T00:00:00.000Z","updated":"2026-11-10T00:00:00.000Z","type":"调研","tags":["AI","Agent","记忆系统","Codex","Claude Code","Cursor"],"category":["🧩 AI框架与Agent","AI 应用核心范式"]},"headers":[],"relativePath":"vault/Knowledge/AI/三大编码 Agent 都没有记忆库.md","filePath":"vault/Knowledge/AI/三大编码 Agent 都没有记忆库.md","lastUpdated":1794303657000}'),C={name:"vault/Knowledge/AI/三大编码 Agent 都没有记忆库.md"};function c(m,t,h,b,q,x){const d=r("VPNolebaseInlineLinkPreview"),n=r("NolebaseGitContributors"),l=r("NolebaseGitChangelog");return u(),i("div",null,[t[7]||(t[7]=p('<h1 id="三大编码-agent-都没有记忆库-只有一堆-markdown-文件" tabindex="-1">三大编码 Agent 都没有记忆库，只有一堆 Markdown 文件 <a class="header-anchor" href="#三大编码-agent-都没有记忆库-只有一堆-markdown-文件" aria-label="Permalink to “三大编码 Agent 都没有记忆库，只有一堆 Markdown 文件”">​</a></h1><p>很多人以为，AI 编程助手&quot;记住你&quot;靠的是一个越来越大的记忆库：聊天越多，向量数据库里塞的东西越多，检索越准。按这个想象，好用的助手应该有一个不断膨胀的私有知识库。</p><p>实际拆开三家主流产品的官方文档，结论是反的。</p><p><strong>Codex、Claude Code、Cursor 的跨会话记忆，单位都是 Markdown 文件。没有一家在官方文档里描述过用向量库检索记忆。</strong> 而且三家的方向一致：常驻的内容越来越小，细节越推越晚，写入端越卡越严。</p><p>这不是技术保守，是需求被重新定义了。</p><h2 id="一、先看反直觉的部分" tabindex="-1">一、先看反直觉的部分 <a class="header-anchor" href="#一、先看反直觉的部分" aria-label="Permalink to “一、先看反直觉的部分”">​</a></h2><p>最容易误解的是&quot;记忆&quot;这个词。它让人联想到数据库：存进去、按需取、取得到就赢了。但编码 Agent 面对的不是&quot;取不到&quot;，是&quot;取太多&quot;。</p><p>一次会话的上下文窗口是有限的。如果每轮都把过去所有会话的摘要灌进去，成本按 token 线性上涨，而且噪声会淹没当前任务。所以你真正要解决的是：<strong>在启动时只放极少的一点东西，剩下的等你真的需要时再去拿。</strong></p><p>三家的做法不同，但都在回答同一个问题。</p><table tabindex="0"><thead><tr><th></th><th>Codex</th><th>Claude Code</th><th>Cursor</th></tr></thead><tbody><tr><td>常驻什么</td><td>记忆摘要 + 合并后的长文</td><td><code>MEMORY.md</code> 前 200 行或 25 KB</td><td>按 frontmatter 条件挂载的规则</td></tr><tr><td>细节在哪</td><td>记忆目录下的其他文件</td><td>独立主题文件，模型按需打开</td><td>本地代码索引 + 对话检索</td></tr><tr><td>谁写</td><td>后台抽取模型 + 合并模型</td><td>会话中模型自写</td><td>人写规则</td></tr><tr><td>自动沉淀</td><td>有，默认关闭</td><td>有，本地会话默认开启</td><td>2.1.x 起移除</td></tr><tr><td>向量检索</td><td>官方文档未描述</td><td>官方文档未描述</td><td>官方明确不存代码 embedding</td></tr></tbody></table><p>注意最后一列。Cursor 是唯一在文档里<strong>明确否认</strong>向量检索的一家：Instant Grep 在本机构建并查询索引，不上传路径或代码，也不存代码 embedding。</p><h2 id="二、codex-把会话-编译-成记忆" tabindex="-1">二、Codex：把会话&quot;编译&quot;成记忆 <a class="header-anchor" href="#二、codex-把会话-编译-成记忆" aria-label="Permalink to “二、Codex：把会话&quot;编译&quot;成记忆”">​</a></h2><p>Codex 的记忆分两层，性质完全不同。</p><p>第一层是 <code>AGENTS.md</code>，它是<strong>指令链，不是记忆</strong>。启动时从全局目录逐级走到当前工作目录，每层取一个文件拼接起来，越靠近 cwd 的越靠后，因此效果上覆盖前面的规则。合并后受 <code>project_doc_max_bytes</code> 限制，默认 32 KiB，超出的部分直接丢弃。</p><p>这层的本质是&quot;人写的、进版本控制的约定&quot;。它会被 git 记录，可以 code review，也可以回滚。</p><p>第二层才是自动记忆。它把记录拆成两段：先按会话抽取，再跨会话合并，两段可以分别指定模型（<code>extract_model</code> 与 <code>consolidation_model</code>）。产物是 Markdown 文件，下次会话只注入摘要层。</p><p>它的门控设计说明了一切：默认关闭；跳过活跃或短命的会话；会话结束不立即处理，空闲 6 小时后才进入候选；剩余额度低于 25% 时跳过后台生成；参与合并的原始记忆默认上限 256 条；30 天未被使用的记忆不再参与合并。</p><p><strong>这些规则没有一条在增加记忆，全在限制记忆。</strong></p><h2 id="三、claude-code-索引与数据分离" tabindex="-1">三、Claude Code：索引与数据分离 <a class="header-anchor" href="#三、claude-code-索引与数据分离" aria-label="Permalink to “三、Claude Code：索引与数据分离”">​</a></h2><p>Claude Code 的核心设计是&quot;索引页 + 数据页&quot;，像数据库。</p><p><code>CLAUDE.md</code> 由人写，放指令；auto memory 由 Claude 自己写，放学到的东西。两者每次会话都加载，但都只是上下文，不是强制配置——官方明确说 <code>CLAUDE.md</code> 作为 user message 放在 system prompt 之后，不保证严格遵从。要强制拦截，得用 hook。</p><p>auto memory 只常驻 <code>MEMORY.md</code> 的前 200 行或 25 KB，先到者为准。其余的每条记忆拆成独立主题文件，模型需要时自己打开。启动成本被固定在一个很小的索引上。</p><p>真正值得抄的是写入端的减法。官方明确排除两类内容：<strong>能从代码库（grep、git）推导的，以及 <code>CLAUDE.md</code> 里已经写过的。</strong> 这是索引能长期压在 200 行内的前提。如果不去重，每次会话都在补重复信息，索引很快就会溢出。</p><p>还有两个细节：接近上限时提醒压缩，超限写入仍然成功，但下次加载会被截断；写记忆文件时在 frontmatter 记 <code>modified</code>，供判断新旧。</p><h2 id="四、cursor-主动放弃自动记忆" tabindex="-1">四、Cursor：主动放弃自动记忆 <a class="header-anchor" href="#四、cursor-主动放弃自动记忆" aria-label="Permalink to “四、Cursor：主动放弃自动记忆”">​</a></h2><p>Cursor 是三者里最激进的。据官方论坛工作人员回复，chat Memories 自 2.1.x 起被有意移除。官方给出的理由是：Memories 与 <code>.mdc</code> 规则差别不大。</p><p>于是记忆被拆成两件事：<strong>稳定约定归 rules</strong>（人写、可评审、可进 git），<strong>历史信息归检索</strong>（本地索引、按需命中）。产品不再判断&quot;哪句话值得长期记住&quot;。</p><p>这是一次收缩，也是一次取舍。代价是没有&quot;用久了它自己懂你&quot;的体验；收益是不会被过期记忆带偏。</p><p>它的规则体系反而因此更细：项目规则进 git，User Rules 随账号同步，Team Rules 后台下发且可强制，冲突时优先级为 Team &gt; Project &gt; User。代码检索走本地 Instant Grep，对话检索给历史 agent 转写建本地索引，并已作为 agent 可主动调用的工具。<code>AGENTS.md</code> 和 <code>CLAUDE.md</code> 也能被读取。</p><h2 id="五、共同的取舍-比差异更值得记" tabindex="-1">五、共同的取舍，比差异更值得记 <a class="header-anchor" href="#五、共同的取舍-比差异更值得记" aria-label="Permalink to “五、共同的取舍，比差异更值得记”">​</a></h2><p>三家在细节上分歧很大，但底层判断高度一致：</p><p><strong>第一，常驻内容必须小。</strong> Codex 只注入摘要，Claude Code 只读 200 行，Cursor 只挂条件规则。没有一家把完整记忆灌进上下文。</p><p><strong>第二，读取必须延迟。</strong> 细节不预先加载，等模型真的需要再去打开文件或搜索。这是把固定成本换成按需成本。</p><p><strong>第三，写入必须做减法。</strong> 这是最容易被忽略的一条。Claude Code 排除代码可推导内容，Codex 用&quot;30 天未使用&quot;做被动剪枝，Cursor 干脆把判断权收回给人。</p><p>差异的根源是对&quot;什么值得记&quot;的信任度不同。Claude Code 信任模型判断，但给它立了明确的排除规则；Codex 信任后台模型，用时间与额度做被动裁剪；Cursor 不信任自动判断，只保留可审计的规则。</p><h2 id="六、这对自建记忆系统意味着什么" tabindex="-1">六、这对自建记忆系统意味着什么 <a class="header-anchor" href="#六、这对自建记忆系统意味着什么" aria-label="Permalink to “六、这对自建记忆系统意味着什么”">​</a></h2><p>如果你在搭自己的 AI 记忆层，这三家的做法能反推出一条原则：</p><p><strong>先设计&quot;不记什么&quot;，再设计&quot;记什么&quot;。</strong></p><p>具体到操作：</p><ol><li><strong>把可推导的内容排除在外。</strong> 代码里能查到的、git 里能查到的，不要写成记忆。它们会过期，而且检索比记忆更准。</li><li><strong>常驻层只放索引。</strong> 一行一条，能定位到细节文件就够。索引的价值是&quot;知道去哪找&quot;，不是&quot;记住全部&quot;。</li><li><strong>给记忆加时间戳和淘汰规则。</strong> 没有失效机制的记忆库，一定会被过期信息污染。</li><li><strong>区分&quot;人写的约定&quot;与&quot;模型写的观察&quot;。</strong> 前者该进版本控制、可评审；后者该可丢弃、可重建。混在一起是大多数自建方案的第一个错误。</li></ol><h2 id="不确定性与边界" tabindex="-1">不确定性与边界 <a class="header-anchor" href="#不确定性与边界" aria-label="Permalink to “不确定性与边界”">​</a></h2><ul><li>Cursor 的 chat Memories 已被移除。任何&quot;Cursor 会自动记住你的偏好&quot;的说法，都要按版本核对。</li><li>Codex 的具体召回算法（是否对记忆文件做 grep）官方未文档化，社区说法属二手，本文不采信为结论。</li><li>三家都在快速迭代，本文结论以 2026-11-09 访问的官方文档为准。</li><li>本文只覆盖官方文档描述的行为，不含第三方记忆插件与自建方案。</li></ul><hr>',43)),g("p",null,[t[3]||(t[3]=e("分厂商的细节见 ",-1)),o(d,{href:"/nebula-blog/vault/Knowledge/AI/Codex 的记忆系统.html"},{default:a(()=>[...t[0]||(t[0]=[e("Codex 的记忆系统",-1)])]),_:1}),t[4]||(t[4]=e("、",-1)),o(d,{href:"/nebula-blog/vault/Knowledge/AI/Claude Code 的记忆系统.html"},{default:a(()=>[...t[1]||(t[1]=[e("Claude Code 的记忆系统",-1)])]),_:1}),t[5]||(t[5]=e("、",-1)),o(d,{href:"/nebula-blog/vault/Knowledge/AI/Cursor 的记忆系统.html"},{default:a(()=>[...t[2]||(t[2]=[e("Cursor 的记忆系统",-1)])]),_:1}),t[6]||(t[6]=e("。",-1))]),o(n),o(l)])}const k=s(C,[["render",c]]);export{f as __pageData,k as default};
